import math

class Solution:
    def maximumGroups(self, grades: list[int]) -> int:
        n = len(grades)
        return int((math.isqrt(1 + 8 * n) - 1) // 2)

class Solution {
public:
    int maximumGroups(std::vector<int>& grades) {
        long long n = grades.size();
        long long k = std::sqrt(1 + 8 * n);
        return (k - 1) / 2;
    }
};

class Solution {
    public int maximumGroups(int[] grades) {
        long n = grades.length;
        return (int) ((Math.sqrt(1 + 8 * n) - 1) / 2);
    }
}

var maximumGroups = function(grades) {
    const n = grades.length;
    return Math.floor((Math.sqrt(1 + 8 * n) - 1) / 2);
};
